#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════
#  WANDERER DEVİR PAKETİ — 5 Eylül 2026
#  Lokalde yapılan işi GitHub'daki repoya taşır. Kendi kendini açar.
# ───────────────────────────────────────────────────────────────
#  NE GETİRİR (yeni dosyalar):
#    TASINABILIR-ZEMIN.md                     çalışma biçimi + hafıza + geçiş envanteri
#    scripts/hafiza-senkron.sh                lokal ↔ repo hafıza köprüsü
#    .claude/hafiza/                          195 hafıza dosyası (1.3 MB) + MEMORY.md
#    .claude/artifacts/tasinabilir-zemin*     yayınlanan raporun kaynağı
#
#  NE DÜZELTİR (varsa; hepsi idempotent — iki kez çalışsa da bozmaz):
#    CLAUDE.md                madde 9: memory aracı yoksa hafıza .claude/hafiza/'dan okunur
#    .claude/settings.json    Stop kancalarındaki mutlak yol → ${CLAUDE_PROJECT_DIR}
#    .claude/artifacts/manifest.json + README.md   raporun arşiv kaydı
#
#  NE YAPMAZ:
#    Var olan hiçbir dosyayı ezmez, silmez, commit atmaz, push etmez.
#    GitHub'da senin sonradan yaptığın düzenlemelere dokunmaz — yalnız ekler
#    ve yukarıdaki üç noktada eksikse tamamlar.
#
#  KULLANIM (repo kökünde):
#      bash WANDERER-DEVIR.sh --prova     # hiçbir şey yazmaz, ne yapacağını söyler
#      bash WANDERER-DEVIR.sh             # uygular
#
#  Sonunda hazır bir `git commit` komutu basar; commit'i sen (ya da oradaki
#  Claude oturumu) atar.
# ═══════════════════════════════════════════════════════════════
set -euo pipefail

PROVA=0
[ "${1:-}" = "--prova" ] || [ "${1:-}" = "--dry-run" ] && PROVA=1

say()  { printf '%s\n' "$*"; }
ok()   { printf '  [+] %s\n' "$*"; }
skip() { printf '  [.] %s\n' "$*"; }
warn() { printf '  [!] %s\n' "$*"; }

# ── 0. Doğru yerde miyiz ─────────────────────────────────────
KOK="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$KOK" ]; then
  say "✗ Burası bir git deposu değil. Wanderer repo kökünde çalıştır."
  exit 1
fi
cd "$KOK"
if [ ! -f "PROTOKOL-FABLE.md" ]; then
  say "✗ Bu Wanderer reposu değil ('PROTOKOL-FABLE.md' yok): $KOK"
  say "  Yanlış repoya açılmasın diye duruyorum."
  exit 1
fi

say ""
say "═══ WANDERER DEVİR PAKETİ ═══"
say "Repo: $KOK"
[ "$PROVA" = "1" ] && say "Mod:  KURU PROVA — hiçbir dosya yazılmayacak"
say ""

# ── 1. Arşivi çöz ────────────────────────────────────────────
say "1) Yeni dosyalar"
GECICI="$(mktemp -d)"
trap 'rm -rf "$GECICI"' EXIT

# Payload: bu dosyanın __ARSIV__ satırından sonrası, base64 tar.gz
# base64: Linux (coreutils) -d ister, eski macOS (BSD) -D. İkisini de dene.
b64coz() { base64 -d 2>/dev/null || base64 -D; }
sed -n '/^__ARSIV__$/,$p' "$0" | tail -n +2 | b64coz | tar xzf - -C "$GECICI"

ADET="$(find "$GECICI" -type f | wc -l | tr -d ' ')"
if [ "$PROVA" = "1" ]; then
  skip "$ADET dosya açılacak (mevcut dosyalar üzerine YAZILIR — bunlar yeni dosyalar)"
  find "$GECICI" -type f | sed "s|$GECICI/|    |" | head -8
  say "    … ve $((ADET - 8)) dosya daha"
else
  # -n YOK: hafıza türevi tazelenmeli. Bu dosyalar zaten yalnız bu işe ait.
  cp -R "$GECICI"/. "$KOK"/
  ok "$ADET dosya yerleştirildi"
fi
say ""

# ── 2. CLAUDE.md — madde 9 ───────────────────────────────────
say "2) CLAUDE.md · hafıza maddesi"
if grep -q "\.claude/hafiza/" CLAUDE.md 2>/dev/null; then
  skip "zaten var — dokunulmadı"
elif [ ! -f CLAUDE.md ]; then
  warn "CLAUDE.md bulunamadı — atlandı"
elif [ "$PROVA" = "1" ]; then
  skip "madde 9 sona eklenecek"
else
  cat >> CLAUDE.md <<'MADDE9'
9. **Hafıza repo DIŞINDA yaşar ama repoya kopyalanır.** Gerçek kaynak
   `~/.claude/projects/<slug>/memory/`; git takipli türevi
   `.claude/hafiza/` (indeks: `.claude/hafiza/MEMORY.md`). **Memory aracın
   yoksa — GitHub/cloud oturumunda olduğu gibi — hafızayı ORADAN oku;**
   indeks satırı özet, dosya gerçektir. Hafızaya yazdığın turda kapanıştan
   önce `./scripts/hafiza-senkron.sh disa` koştur (kapı:
   `… fark` temiz olmalı), sonra commit et. Gerekçe ve geçiş envanteri:
   `TASINABILIR-ZEMIN.md`.
MADDE9
  ok "madde 9 eklendi"
fi
say ""

# ── 3. settings.json — taşınabilir hook yolu ─────────────────
say "3) .claude/settings.json · Stop kancalarının yolu"
S=".claude/settings.json"
if [ ! -f "$S" ]; then
  warn "$S yok — atlandı"
elif ! grep -q '/Users/emregulluce/Desktop/Wanderer AI/scripts/' "$S"; then
  skip "mutlak yol yok — zaten taşınabilir ya da farklı"
elif [ "$PROVA" = "1" ]; then
  skip "mutlak yol → \${CLAUDE_PROJECT_DIR:-…} olarak değiştirilecek"
else
  # macOS/Linux'ta aynı çalışsın diye -i kullanmıyoruz
  sed 's|bash \\"/Users/emregulluce/Desktop/Wanderer AI/scripts/|bash \\"${CLAUDE_PROJECT_DIR:-/Users/emregulluce/Desktop/Wanderer AI}/scripts/|g' \
      "$S" > "$S.yeni"
  if command -v node >/dev/null 2>&1 && ! node -e "JSON.parse(require('fs').readFileSync('$S.yeni','utf8'))" 2>/dev/null; then
    rm -f "$S.yeni"
    warn "düzeltme geçersiz JSON üretti — DOKUNULMADI, elle bak"
  else
    mv "$S.yeni" "$S"
    ok "hook yolları taşınabilir yapıldı"
  fi
fi
say ""

# ── 4. Artifact arşiv kaydı ──────────────────────────────────
say "4) .claude/artifacts · rapor kaydı"
URL="https://claude.ai/code/artifact/9ec687dd-de00-4f3a-bad0-3313f48c6d7d"
M=".claude/artifacts/manifest.json"
if [ ! -f "$M" ]; then
  warn "$M yok — atlandı"
elif grep -q '"tasinabilir-zemin"' "$M"; then
  skip "manifest kaydı zaten var"
elif [ "$PROVA" = "1" ]; then
  skip "manifest'e girdi eklenecek"
elif ! command -v node >/dev/null 2>&1; then
  warn "node yok — manifest girdisini elle ekle"
else
  node -e '
    const fs=require("fs"), p=".claude/artifacts/manifest.json";
    const m=JSON.parse(fs.readFileSync(p,"utf8"));
    m.push({stem:"tasinabilir-zemin",
      file:process.cwd()+"/.claude/artifacts/tasinabilir-zemin.html",
      title:"Taşınabilir Zemin", favicon:"🗝️",
      description:"Wanderer AI\u0027ın çalışma biçimi, hafızası ve GitHub\u0027a geçiş envanteri — ne gitti, ne gitmedi, ne kırık gitti."});
    fs.writeFileSync(p, JSON.stringify(m,null,2)+"\n");
  '
  ok "manifest girdisi eklendi"
fi

R=".claude/artifacts/README.md"
if [ ! -f "$R" ]; then
  warn "$R yok — atlandı"
elif grep -q "9ec687dd" "$R"; then
  skip "README satırı zaten var"
elif [ "$PROVA" = "1" ]; then
  skip "README tablosuna satır eklenecek"
else
  printf '| — | Taşınabilir Zemin · çalışma biçimi, hafıza ve GitHub devri (5 Eyl) | %s |\n' "$URL" >> "$R"
  ok "README satırı eklendi (tablonun sonuna)"
fi
say ""

# ── 5. Özet ──────────────────────────────────────────────────
say "═══ ÖZET ═══"
if [ "$PROVA" = "1" ]; then
  say "Kuru prova bitti — hiçbir dosya değişmedi."
  say "Uygulamak için:  bash WANDERER-DEVIR.sh"
  exit 0
fi

say "Taşınan iş yerinde. Şimdi commit'i sen at:"
say ""
cat <<'KOMUT'
git add TASINABILIR-ZEMIN.md scripts/hafiza-senkron.sh CLAUDE.md \
        .claude/settings.json .claude/hafiza/ .claude/artifacts/
git rm --cached WANDERER-DEVIR.sh 2>/dev/null; rm -f WANDERER-DEVIR.sh
git commit -m "Taşınabilir zemin · Protokol taşındı, hafıza taşınmadı — köprü kuruldu" \
           -m "GitHub'a geçişte model doğru çalıştı ama kör çalıştı: PROTOKOL-FABLE.md
repoda olduğu için taşındı, hafıza (193 dosya, 1.3 MB) repo DIŞINDA olduğu
için taşınmadı. Model hafıza adlarını protokolün konvansiyonundan türetti —
kuralı biliyordu, kuralın uygulanma geçmişini bilmiyordu.

- TASINABILIR-ZEMIN.md — çalışma biçiminin taşınabilir özeti + hafıza
  haritası + geçiş envanteri (giden / gitmeyen / kırık giden)
- .claude/hafiza/ — hafızanın git takipli TÜREVİ (195 dosya)
- scripts/hafiza-senkron.sh — disa/ice/fark; disa --delete kullanır,
  ice kullanmaz (yeni makinede lokal hafızayı ezmemek için)
- CLAUDE.md madde 9 — memory aracı yoksa hafıza .claude/hafiza/'dan okunur
- settings.json — Stop kancaları \${CLAUDE_PROJECT_DIR} ile taşınabilir
- .claude/artifacts/tasinabilir-zemin* — yayınlanan raporun kaynağı

Öz-denetimde iki kırık bulundu ve düzeltildi: rapor önce paralel bir stille
yazılmıştı (rapor.css motoruna taşındı), ve rapor sayıları şişikti
(43 değil 20 yayınlanmış rapor).

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>"
KOMUT
say ""
say "Kurulum sonrası kapı (tavsiye):"
say "  ./build.sh 2>&1 | tail -5"
say "  ./scripts/hafiza-senkron.sh fark     # bu makinede hafıza yoksa 'ice' ile kur"
say ""
exit 0

